package site.leawsic.chess.config;
import java.util.*;
public final class XiangqiAi {private static final int ROOT_WIDTH=30,REPLY_WIDTH=20,FOLLOW_UP_WIDTH=10;private XiangqiAi(){}
 public static Move chooseMove(int[][]b,int side){List<ScoredMove>moves=legalMoves(b,side,ROOT_WIDTH);Move best=null;int bestScore=Integer.MIN_VALUE;for(ScoredMove c:moves){int cap=makeMove(b,c.move);int score;if(Math.abs(cap)==XiangqiConfig.GENERAL)score=10_000_000;else{List<ScoredMove>replies=legalMoves(b,-side,REPLY_WIDTH);if(replies.isEmpty())score=9_000_000;else{int worst=Integer.MAX_VALUE;for(ScoredMove r:replies){int rc=makeMove(b,r.move);int rs=Math.abs(rc)==XiangqiConfig.GENERAL?-10_000_000:bestFollowUp(b,side);undoMove(b,r.move,rc);worst=Math.min(worst,rs);}score=worst+c.orderScore/4;}}undoMove(b,c.move,cap);if(score>bestScore){bestScore=score;best=c.move;}}return best;}
 private static int bestFollowUp(int[][]b,int side){List<ScoredMove>moves=legalMoves(b,side,FOLLOW_UP_WIDTH);if(moves.isEmpty())return -9_000_000;int best=Integer.MIN_VALUE;for(ScoredMove m:moves){int cap=makeMove(b,m.move);int score=Math.abs(cap)==XiangqiConfig.GENERAL?10_000_000:evaluate(b,side)+m.orderScore/3;undoMove(b,m.move,cap);best=Math.max(best,score);}return best;}private static List<ScoredMove> legalMoves(int[][]b,int side,int limit){List<ScoredMove>moves=new ArrayList<>();for(int fy=0;fy<XiangqiConfig.ROWS;fy++)for(int fx=0;fx<XiangqiConfig.COLS;fx++){int p=b[fy][fx];if(XiangqiConfig.color(p)!=side)continue;for(int ty=0;ty<XiangqiConfig.ROWS;ty++)for(int tx=0;tx<XiangqiConfig.COLS;tx++){if(XiangqiConfig.color(b[ty][tx])==side||!XiangqiConfig.isLegalMove(b,fx,fy,tx,ty))continue;Move m=new Move(fx,fy,tx,ty);int cap=makeMove(b,m);boolean legal=!XiangqiConfig.isInCheck(b,side);int score=legal?orderScore(b,p,cap,tx,ty,side):Integer.MIN_VALUE;undoMove(b,m,cap);if(legal)moves.add(new ScoredMove(m,score));}}moves.sort(Comparator.comparingInt(ScoredMove::orderScore).reversed());return moves.size()>limit?new ArrayList<>(moves.subList(0,limit)):moves;}private static int orderScore(int[][]b,int p,int cap,int x,int y,int side){int score=value(Math.abs(cap))*6-value(Math.abs(p))/3;if(Math.abs(cap)==XiangqiConfig.GENERAL)return 10_000_000;if(XiangqiConfig.isInCheck(b,-side))score+=15_000;score+=positionalValue(p,x,y,side)*4;if(inEnemyPalace(x,y,side))score+=180;return score;}private static int evaluate(int[][]b,int side){int score=0;for(int y=0;y<XiangqiConfig.ROWS;y++)for(int x=0;x<XiangqiConfig.COLS;x++){int p=b[y][x];if(p==0)continue;int s=XiangqiConfig.color(p),v=value(Math.abs(p))+positionalValue(p,x,y,s);score+=s==side?v:-v;}if(XiangqiConfig.isInCheck(b,-side))score+=1200;if(XiangqiConfig.isInCheck(b,side))score-=1500;return score;}private static int positionalValue(int p,int x,int y,int side){int advance=side==XiangqiConfig.RED?9-y:y,center=4-Math.abs(x-4);return switch(Math.abs(p)){case XiangqiConfig.ROOK->advance*8+center*5;case XiangqiConfig.CANNON->advance*10+center*7;case XiangqiConfig.HORSE->center*18+advance*5;case XiangqiConfig.SOLDIER->advance<5?advance*12:90+advance*22+center*10;case XiangqiConfig.ADVISOR,XiangqiConfig.ELEPHANT->center*3;default->0;};}private static boolean inEnemyPalace(int x,int y,int side){return x>=3&&x<=5&&(side==XiangqiConfig.RED?y<=2:y>=7);}private static int makeMove(int[][]b,Move m){int cap=b[m.toY][m.toX];b[m.toY][m.toX]=b[m.fromY][m.fromX];b[m.fromY][m.fromX]=0;return cap;}private static void undoMove(int[][]b,Move m,int cap){b[m.fromY][m.fromX]=b[m.toY][m.toX];b[m.toY][m.toX]=cap;}private static int value(int p){return switch(p){case XiangqiConfig.ROOK->900;case XiangqiConfig.CANNON->475;case XiangqiConfig.HORSE->425;case XiangqiConfig.ELEPHANT,XiangqiConfig.ADVISOR->225;case XiangqiConfig.SOLDIER->120;case XiangqiConfig.GENERAL->100_000;default->0;};}public record Move(int fromX,int fromY,int toX,int toY){}private record ScoredMove(Move move,int orderScore){}}
